const std = @import("std");
const Allocator = std.mem.Allocator;

const QuantumCircuit = struct {
    num_qubits: usize,
    gates: std.ArrayList(Gate),
    params: []f64,
    allocator: Allocator,

    const Gate = union(enum) {
        rx: struct { qubit: usize, param_idx: usize },
        ry: struct { qubit: usize, param_idx: usize },
        rz: struct { qubit: usize, param_idx: usize },
        cnot: struct { control: usize, target: usize },
        hadamard: struct { qubit: usize },
    };

    pub fn init(allocator: Allocator, num_qubits: usize, num_params: usize) !QuantumCircuit {
        const params = try allocator.alloc(f64, num_params);
        @memset(params, 0.0);
        return QuantumCircuit{
            .num_qubits = num_qubits,
            .gates = std.ArrayList(Gate).init(allocator),
            .params = params,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *QuantumCircuit) void {
        self.gates.deinit();
        self.allocator.free(self.params);
    }

    pub fn addRX(self: *QuantumCircuit, qubit: usize, param_idx: usize) !void {
        try self.gates.append(.{ .rx = .{ .qubit = qubit, .param_idx = param_idx } });
    }

    pub fn addRY(self: *QuantumCircuit, qubit: usize, param_idx: usize) !void {
        try self.gates.append(.{ .ry = .{ .qubit = qubit, .param_idx = param_idx } });
    }

    pub fn addRZ(self: *QuantumCircuit, qubit: usize, param_idx: usize) !void {
        try self.gates.append(.{ .rz = .{ .qubit = qubit, .param_idx = param_idx } });
    }

    pub fn addCNOT(self: *QuantumCircuit, control: usize, target: usize) !void {
        try self.gates.append(.{ .cnot = .{ .control = control, .target = target } });
    }

    pub fn addHadamard(self: *QuantumCircuit, qubit: usize) !void {
        try self.gates.append(.{ .hadamard = .{ .qubit = qubit } });
    }
};

const StateVector = struct {
    data: []std.math.Complex(f64),
    num_qubits: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_qubits: usize) !StateVector {
        const dim = @as(usize, 1) << @intCast(num_qubits);
        const data = try allocator.alloc(std.math.Complex(f64), dim);
        @memset(data, std.math.Complex(f64){ .re = 0.0, .im = 0.0 });
        data[0] = std.math.Complex(f64){ .re = 1.0, .im = 0.0 };
        return StateVector{
            .data = data,
            .num_qubits = num_qubits,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StateVector) void {
        self.allocator.free(self.data);
    }

    pub fn applyRX(self: *StateVector, qubit: usize, theta: f64) void {
        const dim = @as(usize, 1) << @intCast(self.num_qubits);
        const mask = @as(usize, 1) << @intCast(qubit);
        const cos_val = @cos(theta / 2.0);
        const sin_val = @sin(theta / 2.0);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            if ((i & mask) == 0) {
                const j = i | mask;
                const amp0 = self.data[i];
                const amp1 = self.data[j];
                self.data[i] = .{
                    .re = cos_val * amp0.re + sin_val * amp1.im,
                    .im = cos_val * amp0.im - sin_val * amp1.re,
                };
                self.data[j] = .{
                    .re = cos_val * amp1.re + sin_val * amp0.im,
                    .im = cos_val * amp1.im - sin_val * amp0.re,
                };
            }
        }
    }

    pub fn applyRY(self: *StateVector, qubit: usize, theta: f64) void {
        const dim = @as(usize, 1) << @intCast(self.num_qubits);
        const mask = @as(usize, 1) << @intCast(qubit);
        const cos_val = @cos(theta / 2.0);
        const sin_val = @sin(theta / 2.0);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            if ((i & mask) == 0) {
                const j = i | mask;
                const amp0 = self.data[i];
                const amp1 = self.data[j];
                self.data[i] = .{
                    .re = cos_val * amp0.re - sin_val * amp1.re,
                    .im = cos_val * amp0.im - sin_val * amp1.im,
                };
                self.data[j] = .{
                    .re = sin_val * amp0.re + cos_val * amp1.re,
                    .im = sin_val * amp0.im + cos_val * amp1.im,
                };
            }
        }
    }

    pub fn applyRZ(self: *StateVector, qubit: usize, theta: f64) void {
        const dim = @as(usize, 1) << @intCast(self.num_qubits);
        const mask = @as(usize, 1) << @intCast(qubit);
        const exp_neg = std.math.Complex(f64){
            .re = @cos(-theta / 2.0),
            .im = @sin(-theta / 2.0),
        };
        const exp_pos = std.math.Complex(f64){
            .re = @cos(theta / 2.0),
            .im = @sin(theta / 2.0),
        };

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            const phase = if ((i & mask) == 0) exp_neg else exp_pos;
            const amp = self.data[i];
            self.data[i] = .{
                .re = amp.re * phase.re - amp.im * phase.im,
                .im = amp.re * phase.im + amp.im * phase.re,
            };
        }
    }

    pub fn applyCNOT(self: *StateVector, control: usize, target: usize) void {
        const dim = @as(usize, 1) << @intCast(self.num_qubits);
        const control_mask = @as(usize, 1) << @intCast(control);
        const target_mask = @as(usize, 1) << @intCast(target);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            if ((i & control_mask) != 0 and (i & target_mask) == 0) {
                const j = i | target_mask;
                const temp = self.data[i];
                self.data[i] = self.data[j];
                self.data[j] = temp;
            }
        }
    }

    pub fn applyHadamard(self: *StateVector, qubit: usize) void {
        const dim = @as(usize, 1) << @intCast(self.num_qubits);
        const mask = @as(usize, 1) << @intCast(qubit);
        const inv_sqrt2 = 1.0 / @sqrt(2.0);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            if ((i & mask) == 0) {
                const j = i | mask;
                const amp0 = self.data[i];
                const amp1 = self.data[j];
                self.data[i] = .{
                    .re = inv_sqrt2 * (amp0.re + amp1.re),
                    .im = inv_sqrt2 * (amp0.im + amp1.im),
                };
                self.data[j] = .{
                    .re = inv_sqrt2 * (amp0.re - amp1.re),
                    .im = inv_sqrt2 * (amp0.im - amp1.im),
                };
            }
        }
    }

    pub fn measureExpectation(self: *StateVector, observable: []const f64) f64 {
        var expectation: f64 = 0.0;
        for (self.data, 0..) |amp, i| {
            const prob = amp.re * amp.re + amp.im * amp.im;
            expectation += prob * observable[i];
        }
        return expectation;
    }
};

const VQEOptimizer = struct {
    circuit: *QuantumCircuit,
    learning_rate: f64,
    max_iterations: usize,
    tolerance: f64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, circuit: *QuantumCircuit, learning_rate: f64) VQEOptimizer {
        return VQEOptimizer{
            .circuit = circuit,
            .learning_rate = learning_rate,
            .max_iterations = 1000,
            .tolerance = 1e-6,
            .allocator = allocator,
        };
    }

    pub fn optimize(self: *VQEOptimizer, hamiltonian: []const f64) !f64 {
        var state = try StateVector.init(self.allocator, self.circuit.num_qubits);
        defer state.deinit();

        var best_energy: f64 = std.math.inf(f64);
        var iteration: usize = 0;

        while (iteration < self.max_iterations) : (iteration += 1) {
            state = try StateVector.init(self.allocator, self.circuit.num_qubits);
            defer state.deinit();

            for (self.circuit.gates.items) |gate| {
                switch (gate) {
                    .rx => |g| state.applyRX(g.qubit, self.circuit.params[g.param_idx]),
                    .ry => |g| state.applyRY(g.qubit, self.circuit.params[g.param_idx]),
                    .rz => |g| state.applyRZ(g.qubit, self.circuit.params[g.param_idx]),
                    .cnot => |g| state.applyCNOT(g.control, g.target),
                    .hadamard => |g| state.applyHadamard(g.qubit),
                }
            }

            const energy = state.measureExpectation(hamiltonian);

            if (energy < best_energy) {
                best_energy = energy;
            }

            if (iteration > 0 and @abs(energy - best_energy) < self.tolerance) {
                break;
            }

            for (self.circuit.params, 0..) |*param, idx| {
                const delta = 0.01;
                param.* += delta;

                state = try StateVector.init(self.allocator, self.circuit.num_qubits);
                defer state.deinit();

                for (self.circuit.gates.items) |gate| {
                    switch (gate) {
                        .rx => |g| state.applyRX(g.qubit, self.circuit.params[g.param_idx]),
                        .ry => |g| state.applyRY(g.qubit, self.circuit.params[g.param_idx]),
                        .rz => |g| state.applyRZ(g.qubit, self.circuit.params[g.param_idx]),
                        .cnot => |g| state.applyCNOT(g.control, g.target),
                        .hadamard => |g| state.applyHadamard(g.qubit),
                    }
                }

                const energy_plus = state.measureExpectation(hamiltonian);
                param.* -= 2.0 * delta;

                state = try StateVector.init(self.allocator, self.circuit.num_qubits);
                defer state.deinit();

                for (self.circuit.gates.items) |gate| {
                    switch (gate) {
                        .rx => |g| state.applyRX(g.qubit, self.circuit.params[g.param_idx]),
                        .ry => |g| state.applyRY(g.qubit, self.circuit.params[g.param_idx]),
                        .rz => |g| state.applyRZ(g.qubit, self.circuit.params[g.param_idx]),
                        .cnot => |g| state.applyCNOT(g.control, g.target),
                        .hadamard => |g| state.applyHadamard(g.qubit),
                    }
                }

                const energy_minus = state.measureExpectation(hamiltonian);
                const gradient = (energy_plus - energy_minus) / (2.0 * delta);

                param.* += delta - self.learning_rate * gradient;
                _ = idx;
            }
        }

        return best_energy;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var circuit = try QuantumCircuit.init(allocator, 4, 8);
    defer circuit.deinit();

    try circuit.addHadamard(0);
    try circuit.addRY(0, 0);
    try circuit.addRY(1, 1);
    try circuit.addCNOT(0, 1);
    try circuit.addRY(2, 2);
    try circuit.addRY(3, 3);
    try circuit.addCNOT(1, 2);
    try circuit.addCNOT(2, 3);
    try circuit.addRX(0, 4);
    try circuit.addRX(1, 5);
    try circuit.addRX(2, 6);
    try circuit.addRX(3, 7);

    const dim = @as(usize, 1) << @intCast(circuit.num_qubits);
    const hamiltonian = try allocator.alloc(f64, dim);
    defer allocator.free(hamiltonian);

    for (hamiltonian, 0..) |*h, i| {
        h.* = -1.0 + 0.1 * @as(f64, @floatFromInt(i));
    }

    var optimizer = VQEOptimizer.init(allocator, &circuit, 0.1);
    const ground_state_energy = try optimizer.optimize(hamiltonian);

    std.debug.print("VQE Ground State Energy: {d:.6}\n", .{ground_state_energy});
}
