const std = @import("std");
const Allocator = std.mem.Allocator;

const WeakTeacher = struct {
    model_dim: usize,
    vocab_size: usize,
    weights: []f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, model_dim: usize, vocab_size: usize) !WeakTeacher {
        const weights = try allocator.alloc(f32, model_dim * vocab_size);
        var prng = std.Random.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = prng.random();

        for (weights) |*w| {
            w.* = random.floatNorm(f32) * 0.02;
        }

        return WeakTeacher{
            .model_dim = model_dim,
            .vocab_size = vocab_size,
            .weights = weights,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *WeakTeacher) void {
        self.allocator.free(self.weights);
    }

    pub fn forward(self: *WeakTeacher, input: []const f32, output: []f32) void {
        @memset(output, 0.0);

        for (0..self.vocab_size) |v| {
            for (0..self.model_dim) |d| {
                output[v] += input[d] * self.weights[d * self.vocab_size + v];
            }
        }

        var sum: f32 = 0.0;
        for (output) |*o| {
            o.* = @exp(o.*);
            sum += o.*;
        }
        for (output) |*o| {
            o.* /= sum;
        }
    }
};

const StrongStudent = struct {
    model_dim: usize,
    hidden_dim: usize,
    vocab_size: usize,
    w1: []f32,
    w2: []f32,
    w3: []f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, model_dim: usize, hidden_dim: usize, vocab_size: usize) !StrongStudent {
        const w1 = try allocator.alloc(f32, model_dim * hidden_dim);
        const w2 = try allocator.alloc(f32, hidden_dim * hidden_dim);
        const w3 = try allocator.alloc(f32, hidden_dim * vocab_size);

        var prng = std.Random.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = prng.random();

        for (w1) |*w| w.* = random.floatNorm(f32) * 0.02;
        for (w2) |*w| w.* = random.floatNorm(f32) * 0.02;
        for (w3) |*w| w.* = random.floatNorm(f32) * 0.02;

        return StrongStudent{
            .model_dim = model_dim,
            .hidden_dim = hidden_dim,
            .vocab_size = vocab_size,
            .w1 = w1,
            .w2 = w2,
            .w3 = w3,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StrongStudent) void {
        self.allocator.free(self.w1);
        self.allocator.free(self.w2);
        self.allocator.free(self.w3);
    }

    pub fn forward(self: *StrongStudent, input: []const f32, output: []f32, temp: []f32) void {
        @memset(temp, 0.0);

        for (0..self.hidden_dim) |h| {
            for (0..self.model_dim) |d| {
                temp[h] += input[d] * self.w1[d * self.hidden_dim + h];
            }
            temp[h] = if (temp[h] > 0) temp[h] else 0;
        }

        var hidden2 = temp[self.hidden_dim..];
        @memset(hidden2[0..self.hidden_dim], 0.0);

        for (0..self.hidden_dim) |h2| {
            for (0..self.hidden_dim) |h1| {
                hidden2[h2] += temp[h1] * self.w2[h1 * self.hidden_dim + h2];
            }
            hidden2[h2] = if (hidden2[h2] > 0) hidden2[h2] else 0;
        }

        @memset(output, 0.0);

        for (0..self.vocab_size) |v| {
            for (0..self.hidden_dim) |h| {
                output[v] += hidden2[h] * self.w3[h * self.vocab_size + v];
            }
        }

        var sum: f32 = 0.0;
        for (output) |*o| {
            o.* = @exp(o.*);
            sum += o.*;
        }
        for (output) |*o| {
            o.* /= sum;
        }
    }
};

const W2SGTrainer = struct {
    teacher: *WeakTeacher,
    student: *StrongStudent,
    confidence_weight: f32,
    kl_weight: f32,
    learning_rate: f32,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        teacher: *WeakTeacher,
        student: *StrongStudent,
        confidence_weight: f32,
        kl_weight: f32,
        learning_rate: f32,
    ) W2SGTrainer {
        return W2SGTrainer{
            .teacher = teacher,
            .student = student,
            .confidence_weight = confidence_weight,
            .kl_weight = kl_weight,
            .learning_rate = learning_rate,
            .allocator = allocator,
        };
    }

    pub fn trainStep(
        self: *W2SGTrainer,
        inputs: []const []const f32,
        labels: []const usize,
    ) !f32 {
        var total_loss: f32 = 0.0;

        var teacher_output = try self.allocator.alloc(f32, self.teacher.vocab_size);
        defer self.allocator.free(teacher_output);

        var student_output = try self.allocator.alloc(f32, self.student.vocab_size);
        defer self.allocator.free(student_output);

        var temp = try self.allocator.alloc(f32, self.student.hidden_dim * 2);
        defer self.allocator.free(temp);

        var w1_grad = try self.allocator.alloc(f32, self.student.w1.len);
        defer self.allocator.free(w1_grad);
        @memset(w1_grad, 0.0);

        var w2_grad = try self.allocator.alloc(f32, self.student.w2.len);
        defer self.allocator.free(w2_grad);
        @memset(w2_grad, 0.0);

        var w3_grad = try self.allocator.alloc(f32, self.student.w3.len);
        defer self.allocator.free(w3_grad);
        @memset(w3_grad, 0.0);

        for (inputs, labels) |input, label| {
            self.teacher.forward(input, teacher_output);
            self.student.forward(input, student_output, temp);

            var teacher_confidence: f32 = 0.0;
            for (teacher_output) |p| {
                if (p > 0) {
                    teacher_confidence -= p * @log(p);
                }
            }
            teacher_confidence = @exp(-teacher_confidence);

            var ce_loss: f32 = -@log(student_output[label] + 1e-10);

            var kl_loss: f32 = 0.0;
            for (teacher_output, student_output) |t, s| {
                if (t > 1e-10) {
                    kl_loss += t * @log(t / (s + 1e-10));
                }
            }

            const confidence_loss = teacher_confidence * ce_loss;
            const loss = confidence_loss + self.kl_weight * kl_loss;
            total_loss += loss;

            for (0..self.student.vocab_size) |v| {
                var grad = student_output[v];
                if (v == label) {
                    grad -= 1.0;
                }
                grad *= self.confidence_weight * teacher_confidence;

                if (teacher_output[v] > 1e-10) {
                    grad += self.kl_weight * (student_output[v] - teacher_output[v]);
                }

                for (0..self.student.hidden_dim) |h| {
                    w3_grad[h * self.student.vocab_size + v] += grad * temp[self.student.hidden_dim + h];
                }
            }
        }

        const batch_size = @as(f32, @floatFromInt(inputs.len));
        for (self.student.w1, w1_grad) |*w, g| {
            w.* -= self.learning_rate * g / batch_size;
        }
        for (self.student.w2, w2_grad) |*w, g| {
            w.* -= self.learning_rate * g / batch_size;
        }
        for (self.student.w3, w3_grad) |*w, g| {
            w.* -= self.learning_rate * g / batch_size;
        }

        return total_loss / batch_size;
    }

    pub fn evaluate(
        self: *W2SGTrainer,
        inputs: []const []const f32,
        labels: []const usize,
    ) !f32 {
        var correct: usize = 0;

        var student_output = try self.allocator.alloc(f32, self.student.vocab_size);
        defer self.allocator.free(student_output);

        var temp = try self.allocator.alloc(f32, self.student.hidden_dim * 2);
        defer self.allocator.free(temp);

        for (inputs, labels) |input, label| {
            self.student.forward(input, student_output, temp);

            var max_idx: usize = 0;
            var max_val: f32 = student_output[0];
            for (student_output, 0..) |val, idx| {
                if (val > max_val) {
                    max_val = val;
                    max_idx = idx;
                }
            }

            if (max_idx == label) {
                correct += 1;
            }
        }

        return @as(f32, @floatFromInt(correct)) / @as(f32, @floatFromInt(inputs.len));
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const model_dim = 128;
    const hidden_dim = 512;
    const vocab_size = 1000;

    var teacher = try WeakTeacher.init(allocator, model_dim, vocab_size);
    defer teacher.deinit();

    var student = try StrongStudent.init(allocator, model_dim, hidden_dim, vocab_size);
    defer student.deinit();

    var trainer = W2SGTrainer.init(allocator, &teacher, &student, 0.5, 0.3, 0.001);

    const batch_size = 32;
    const num_batches = 100;

    var prng = std.Random.DefaultPrng.init(@intCast(std.time.timestamp()));
    const random = prng.random();

    var inputs = try allocator.alloc([]f32, batch_size);
    defer {
        for (inputs) |input| allocator.free(input);
        allocator.free(inputs);
    }

    for (inputs) |*input| {
        input.* = try allocator.alloc(f32, model_dim);
        for (input.*) |*val| {
            val.* = random.floatNorm(f32);
        }
    }

    var labels = try allocator.alloc(usize, batch_size);
    defer allocator.free(labels);

    for (labels) |*label| {
        label.* = random.intRangeAtMost(usize, 0, vocab_size - 1);
    }

    var epoch: usize = 0;
    while (epoch < num_batches) : (epoch += 1) {
        const loss = try trainer.trainStep(inputs, labels);

        if (epoch % 10 == 0) {
            const accuracy = try trainer.evaluate(inputs, labels);
            std.debug.print("Epoch {d}: Loss = {d:.4}, Accuracy = {d:.4}\n", .{ epoch, loss, accuracy });
        }
    }
}
