const std = @import("std");
const Allocator = std.mem.Allocator;

const Event = struct {
    timestamp: i64,
    entity_id: []const u8,
    event_type: []const u8,
    payload: []const u8,
    metadata: std.StringHashMap([]const u8),

    pub fn deinit(self: *Event, allocator: Allocator) void {
        allocator.free(self.entity_id);
        allocator.free(self.event_type);
        allocator.free(self.payload);
        self.metadata.deinit();
    }
};

const EnrichedEvent = struct {
    base_event: Event,
    context: []const u8,
    references: std.ArrayList([]const u8),
    confidence: f32,

    pub fn deinit(self: *EnrichedEvent, allocator: Allocator) void {
        self.base_event.deinit(allocator);
        allocator.free(self.context);
        for (self.references.items) |ref| {
            allocator.free(ref);
        }
        self.references.deinit();
    }
};

const EventStream = struct {
    events: std.ArrayList(Event),
    buffer_size: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, buffer_size: usize) EventStream {
        return EventStream{
            .events = std.ArrayList(Event).init(allocator),
            .buffer_size = buffer_size,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EventStream) void {
        for (self.events.items) |*event| {
            event.deinit(self.allocator);
        }
        self.events.deinit();
    }

    pub fn push(self: *EventStream, event: Event) !void {
        try self.events.append(event);
        if (self.events.items.len > self.buffer_size) {
            var old = self.events.orderedRemove(0);
            old.deinit(self.allocator);
        }
    }

    pub fn getRecent(self: *EventStream, count: usize) []const Event {
        const available = @min(count, self.events.items.len);
        const start = self.events.items.len - available;
        return self.events.items[start..];
    }
};

const EntityGraph = struct {
    nodes: std.StringHashMap(std.ArrayList([]const u8)),
    allocator: Allocator,

    pub fn init(allocator: Allocator) EntityGraph {
        return EntityGraph{
            .nodes = std.StringHashMap(std.ArrayList([]const u8)).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EntityGraph) void {
        var it = self.nodes.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            for (entry.value_ptr.items) |edge| {
                self.allocator.free(edge);
            }
            entry.value_ptr.deinit();
        }
        self.nodes.deinit();
    }

    pub fn addEdge(self: *EntityGraph, from: []const u8, to: []const u8) !void {
        const from_copy = try self.allocator.dupe(u8, from);
        const to_copy = try self.allocator.dupe(u8, to);

        var result = try self.nodes.getOrPut(from_copy);
        if (!result.found_existing) {
            result.value_ptr.* = std.ArrayList([]const u8).init(self.allocator);
        }
        try result.value_ptr.append(to_copy);
    }

    pub fn getNeighbors(self: *EntityGraph, entity: []const u8) ?[]const []const u8 {
        if (self.nodes.get(entity)) |neighbors| {
            return neighbors.items;
        }
        return null;
    }
};

const Enricher = struct {
    entity_graph: EntityGraph,
    context_cache: std.StringHashMap([]const u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator) Enricher {
        return Enricher{
            .entity_graph = EntityGraph.init(allocator),
            .context_cache = std.StringHashMap([]const u8).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Enricher) void {
        self.entity_graph.deinit();
        var it = self.context_cache.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.context_cache.deinit();
    }

    pub fn enrich(self: *Enricher, event: Event) !EnrichedEvent {
        var references = std.ArrayList([]const u8).init(self.allocator);

        if (self.entity_graph.getNeighbors(event.entity_id)) |neighbors| {
            for (neighbors) |neighbor| {
                const ref_copy = try self.allocator.dupe(u8, neighbor);
                try references.append(ref_copy);
            }
        }

        const context = if (self.context_cache.get(event.entity_id)) |ctx|
            try self.allocator.dupe(u8, ctx)
        else
            try std.fmt.allocPrint(self.allocator, "default_context_{s}", .{event.event_type});

        const confidence: f32 = @as(f32, @floatFromInt(references.items.len)) / 10.0;

        return EnrichedEvent{
            .base_event = event,
            .context = context,
            .references = references,
            .confidence = @min(confidence, 1.0),
        };
    }

    pub fn updateContext(self: *Enricher, entity_id: []const u8, context: []const u8) !void {
        const entity_copy = try self.allocator.dupe(u8, entity_id);
        const context_copy = try self.allocator.dupe(u8, context);
        try self.context_cache.put(entity_copy, context_copy);
    }
};

const PubSubBus = struct {
    subscribers: std.StringHashMap(std.ArrayList(*const fn (EnrichedEvent) void)),
    allocator: Allocator,

    pub fn init(allocator: Allocator) PubSubBus {
        return PubSubBus{
            .subscribers = std.StringHashMap(std.ArrayList(*const fn (EnrichedEvent) void)).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *PubSubBus) void {
        var it = self.subscribers.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit();
        }
        self.subscribers.deinit();
    }

    pub fn subscribe(self: *PubSubBus, topic: []const u8, handler: *const fn (EnrichedEvent) void) !void {
        const topic_copy = try self.allocator.dupe(u8, topic);
        var result = try self.subscribers.getOrPut(topic_copy);
        if (!result.found_existing) {
            result.value_ptr.* = std.ArrayList(*const fn (EnrichedEvent) void).init(self.allocator);
        }
        try result.value_ptr.append(handler);
    }

    pub fn publish(self: *PubSubBus, topic: []const u8, event: EnrichedEvent) void {
        if (self.subscribers.get(topic)) |handlers| {
            for (handlers.items) |handler| {
                handler(event);
            }
        }
    }
};

const JadeProcessor = struct {
    stream: EventStream,
    enricher: Enricher,
    bus: PubSubBus,
    allocator: Allocator,

    pub fn init(allocator: Allocator, buffer_size: usize) JadeProcessor {
        return JadeProcessor{
            .stream = EventStream.init(allocator, buffer_size),
            .enricher = Enricher.init(allocator),
            .bus = PubSubBus.init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JadeProcessor) void {
        self.stream.deinit();
        self.enricher.deinit();
        self.bus.deinit();
    }

    pub fn processEvent(self: *JadeProcessor, event: Event) !void {
        try self.stream.push(event);

        const enriched = try self.enricher.enrich(event);

        self.bus.publish(event.event_type, enriched);
    }

    pub fn buildGraph(self: *JadeProcessor, relationships: []const struct { from: []const u8, to: []const u8 }) !void {
        for (relationships) |rel| {
            try self.enricher.entity_graph.addEdge(rel.from, rel.to);
        }
    }
};

fn exampleHandler(event: EnrichedEvent) void {
    std.debug.print("Processed event: {s} with confidence {d:.2}\n", .{ event.base_event.event_type, event.confidence });
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var processor = JadeProcessor.init(allocator, 1000);
    defer processor.deinit();

    try processor.bus.subscribe("user_action", exampleHandler);

    const relationships = [_]struct { from: []const u8, to: []const u8 }{
        .{ .from = "user_123", .to = "product_456" },
        .{ .from = "user_123", .to = "product_789" },
        .{ .from = "product_456", .to = "category_electronics" },
    };
    try processor.buildGraph(&relationships);

    try processor.enricher.updateContext("user_123", "premium_customer");

    var metadata = std.StringHashMap([]const u8).init(allocator);
    defer metadata.deinit();

    try metadata.put("ip", "192.168.1.1");
    try metadata.put("device", "mobile");

    const event = Event{
        .timestamp = std.time.timestamp(),
        .entity_id = try allocator.dupe(u8, "user_123"),
        .event_type = try allocator.dupe(u8, "user_action"),
        .payload = try allocator.dupe(u8, "{\"action\":\"view\",\"item\":\"product_456\"}"),
        .metadata = metadata,
    };

    try processor.processEvent(event);

    const recent = processor.stream.getRecent(5);
    std.debug.print("Recent events: {d}\n", .{recent.len});
}
