const std = @import("std");
const Allocator = std.mem.Allocator;

const Constraint = struct {
    rule: []const u8,
    priority: u8,
    enabled: bool,

    pub fn deinit(self: *Constraint, allocator: Allocator) void {
        allocator.free(self.rule);
    }
};

const ConstitutionalLayer = struct {
    constraints: std.ArrayList(Constraint),
    violation_log: std.ArrayList([]const u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator) ConstitutionalLayer {
        return ConstitutionalLayer{
            .constraints = std.ArrayList(Constraint).init(allocator),
            .violation_log = std.ArrayList([]const u8).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ConstitutionalLayer) void {
        for (self.constraints.items) |*constraint| {
            constraint.deinit(self.allocator);
        }
        self.constraints.deinit();
        for (self.violation_log.items) |log| {
            self.allocator.free(log);
        }
        self.violation_log.deinit();
    }

    pub fn addConstraint(self: *ConstitutionalLayer, rule: []const u8, priority: u8) !void {
        const rule_copy = try self.allocator.dupe(u8, rule);
        try self.constraints.append(Constraint{
            .rule = rule_copy,
            .priority = priority,
            .enabled = true,
        });
    }

    pub fn evaluate(self: *ConstitutionalLayer, output: []const u8) !bool {
        for (self.constraints.items) |constraint| {
            if (!constraint.enabled) continue;

            if (std.mem.indexOf(u8, output, "harmful") != null or
                std.mem.indexOf(u8, output, "illegal") != null or
                std.mem.indexOf(u8, output, "unsafe") != null)
            {
                const log_entry = try std.fmt.allocPrint(
                    self.allocator,
                    "Violation: {s} at priority {d}",
                    .{ constraint.rule, constraint.priority },
                );
                try self.violation_log.append(log_entry);
                return false;
            }
        }
        return true;
    }

    pub fn getViolations(self: *ConstitutionalLayer) []const []const u8 {
        return self.violation_log.items;
    }
};

const FormalProof = struct {
    theorem: []const u8,
    proof_steps: std.ArrayList([]const u8),
    verified: bool,
    allocator: Allocator,

    pub fn init(allocator: Allocator, theorem: []const u8) !FormalProof {
        return FormalProof{
            .theorem = try allocator.dupe(u8, theorem),
            .proof_steps = std.ArrayList([]const u8).init(allocator),
            .verified = false,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *FormalProof) void {
        self.allocator.free(self.theorem);
        for (self.proof_steps.items) |step| {
            self.allocator.free(step);
        }
        self.proof_steps.deinit();
    }

    pub fn addStep(self: *FormalProof, step: []const u8) !void {
        const step_copy = try self.allocator.dupe(u8, step);
        try self.proof_steps.append(step_copy);
    }

    pub fn verify(self: *FormalProof) bool {
        if (self.proof_steps.items.len < 2) return false;

        for (self.proof_steps.items) |step| {
            if (std.mem.indexOf(u8, step, "axiom") != null or
                std.mem.indexOf(u8, step, "lemma") != null or
                std.mem.indexOf(u8, step, "qed") != null)
            {
                continue;
            } else {
                return false;
            }
        }

        self.verified = true;
        return true;
    }
};

const SafetyVerifier = struct {
    constitutional: ConstitutionalLayer,
    proofs: std.ArrayList(FormalProof),
    trust_score: f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator) SafetyVerifier {
        return SafetyVerifier{
            .constitutional = ConstitutionalLayer.init(allocator),
            .proofs = std.ArrayList(FormalProof).init(allocator),
            .trust_score = 1.0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SafetyVerifier) void {
        self.constitutional.deinit();
        for (self.proofs.items) |*proof| {
            proof.deinit();
        }
        self.proofs.deinit();
    }

    pub fn addSafetyRule(self: *SafetyVerifier, rule: []const u8, priority: u8) !void {
        try self.constitutional.addConstraint(rule, priority);
    }

    pub fn addProof(self: *SafetyVerifier, proof: FormalProof) !void {
        try self.proofs.append(proof);
    }

    pub fn verifyOutput(self: *SafetyVerifier, output: []const u8) !struct { safe: bool, score: f32 } {
        const constitutional_pass = try self.constitutional.evaluate(output);

        var verified_proofs: usize = 0;
        for (self.proofs.items) |*proof| {
            if (proof.verify()) {
                verified_proofs += 1;
            }
        }

        const proof_ratio = if (self.proofs.items.len > 0)
            @as(f32, @floatFromInt(verified_proofs)) / @as(f32, @floatFromInt(self.proofs.items.len))
        else
            0.5;

        self.trust_score = if (constitutional_pass) proof_ratio else 0.0;

        return .{
            .safe = constitutional_pass and self.trust_score > 0.5,
            .score = self.trust_score,
        };
    }

    pub fn getTrustScore(self: *SafetyVerifier) f32 {
        return self.trust_score;
    }
};

const AlignmentMetrics = struct {
    helpfulness: f32,
    harmlessness: f32,
    honesty: f32,
    consistency: f32,

    pub fn compute(output: []const u8, reference: []const u8) AlignmentMetrics {
        const helpfulness = blk: {
            var score: f32 = 0.8;
            if (output.len > reference.len / 2) score += 0.1;
            if (std.mem.indexOf(u8, output, "help") != null) score += 0.1;
            break :blk @min(score, 1.0);
        };

        const harmlessness = blk: {
            var score: f32 = 1.0;
            if (std.mem.indexOf(u8, output, "harmful") != null) score -= 0.5;
            if (std.mem.indexOf(u8, output, "danger") != null) score -= 0.3;
            break :blk @max(score, 0.0);
        };

        const honesty = blk: {
            var score: f32 = 0.9;
            if (std.mem.indexOf(u8, output, "uncertain") != null) score += 0.05;
            if (std.mem.indexOf(u8, output, "probably") != null) score += 0.05;
            break :blk @min(score, 1.0);
        };

        const consistency = blk: {
            var score: f32 = 0.85;
            const overlap = computeOverlap(output, reference);
            score += overlap * 0.15;
            break :blk @min(score, 1.0);
        };

        return AlignmentMetrics{
            .helpfulness = helpfulness,
            .harmlessness = harmlessness,
            .honesty = honesty,
            .consistency = consistency,
        };
    }

    fn computeOverlap(a: []const u8, b: []const u8) f32 {
        var matches: usize = 0;
        const min_len = @min(a.len, b.len);
        const window = @min(min_len, 100);

        var i: usize = 0;
        while (i < window) : (i += 1) {
            if (a[i] == b[i]) matches += 1;
        }

        return @as(f32, @floatFromInt(matches)) / @as(f32, @floatFromInt(window));
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var verifier = SafetyVerifier.init(allocator);
    defer verifier.deinit();

    try verifier.addSafetyRule("no_harm", 10);
    try verifier.addSafetyRule("no_illegal_content", 10);
    try verifier.addSafetyRule("factual_accuracy", 8);
    try verifier.addSafetyRule("privacy_protection", 9);

    var proof1 = try FormalProof.init(allocator, "output_safety_theorem");
    defer proof1.deinit();
    try proof1.addStep("axiom: all_outputs_filtered");
    try proof1.addStep("lemma: constitutional_constraints_applied");
    try proof1.addStep("qed: output_safe");

    try verifier.addProof(proof1);

    const test_output = "This is a helpful and safe response that assists the user.";
    const reference = "This is a reference response for comparison.";

    const result = try verifier.verifyOutput(test_output);
    std.debug.print("Safety verification: {}\n", .{result.safe});
    std.debug.print("Trust score: {d:.2}\n", .{result.score});

    const metrics = AlignmentMetrics.compute(test_output, reference);
    std.debug.print("Helpfulness: {d:.2}\n", .{metrics.helpfulness});
    std.debug.print("Harmlessness: {d:.2}\n", .{metrics.harmlessness});
    std.debug.print("Honesty: {d:.2}\n", .{metrics.honesty});
    std.debug.print("Consistency: {d:.2}\n", .{metrics.consistency});

    const unsafe_output = "This output contains harmful content.";
    const unsafe_result = try verifier.verifyOutput(unsafe_output);
    std.debug.print("\nUnsafe output verification: {}\n", .{unsafe_result.safe});
    std.debug.print("Trust score: {d:.2}\n", .{unsafe_result.score});

    const violations = verifier.constitutional.getViolations();
    std.debug.print("Violations logged: {d}\n", .{violations.len});
    for (violations) |violation| {
        std.debug.print("  - {s}\n", .{violation});
    }
}
