const std = @import("std");
const Allocator = std.mem.Allocator;

const GraphNode = struct {
    id: usize,
    features: []f32,
    neighbors: std.ArrayList(usize),
    degree: usize,

    pub fn init(allocator: Allocator, id: usize, feature_dim: usize) !GraphNode {
        const features = try allocator.alloc(f32, feature_dim);
        @memset(features, 0.0);
        return GraphNode{
            .id = id,
            .features = features,
            .neighbors = std.ArrayList(usize).init(allocator),
            .degree = 0,
        };
    }

    pub fn deinit(self: *GraphNode, allocator: Allocator) void {
        allocator.free(self.features);
        self.neighbors.deinit();
    }

    pub fn addNeighbor(self: *GraphNode, neighbor_id: usize) !void {
        try self.neighbors.append(neighbor_id);
        self.degree += 1;
    }
};

const RelationalGraph = struct {
    nodes: std.ArrayList(GraphNode),
    edge_types: std.StringHashMap(usize),
    feature_dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, feature_dim: usize) RelationalGraph {
        return RelationalGraph{
            .nodes = std.ArrayList(GraphNode).init(allocator),
            .edge_types = std.StringHashMap(usize).init(allocator),
            .feature_dim = feature_dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *RelationalGraph) void {
        for (self.nodes.items) |*node| {
            node.deinit(self.allocator);
        }
        self.nodes.deinit();
        var it = self.edge_types.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.edge_types.deinit();
    }

    pub fn addNode(self: *RelationalGraph) !usize {
        const id = self.nodes.items.len;
        const node = try GraphNode.init(self.allocator, id, self.feature_dim);
        try self.nodes.append(node);
        return id;
    }

    pub fn addEdge(self: *RelationalGraph, from: usize, to: usize, edge_type: []const u8) !void {
        if (from >= self.nodes.items.len or to >= self.nodes.items.len) {
            return error.InvalidNodeId;
        }

        try self.nodes.items[from].addNeighbor(to);

        if (!self.edge_types.contains(edge_type)) {
            const type_copy = try self.allocator.dupe(u8, edge_type);
            try self.edge_types.put(type_copy, self.edge_types.count());
        }
    }

    pub fn setNodeFeatures(self: *RelationalGraph, node_id: usize, features: []const f32) !void {
        if (node_id >= self.nodes.items.len) {
            return error.InvalidNodeId;
        }
        if (features.len != self.feature_dim) {
            return error.InvalidFeatureDim;
        }
        @memcpy(self.nodes.items[node_id].features, features);
    }
};

const GNNLayer = struct {
    input_dim: usize,
    output_dim: usize,
    weights: []f32,
    bias: []f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, input_dim: usize, output_dim: usize) !GNNLayer {
        const weights = try allocator.alloc(f32, input_dim * output_dim);
        const bias = try allocator.alloc(f32, output_dim);

        var prng = std.Random.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = prng.random();

        const scale = @sqrt(2.0 / @as(f32, @floatFromInt(input_dim)));
        for (weights) |*w| {
            w.* = random.floatNorm(f32) * scale;
        }
        @memset(bias, 0.0);

        return GNNLayer{
            .input_dim = input_dim,
            .output_dim = output_dim,
            .weights = weights,
            .bias = bias,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *GNNLayer) void {
        self.allocator.free(self.weights);
        self.allocator.free(self.bias);
    }

    pub fn forward(self: *GNNLayer, graph: *RelationalGraph, output: [][]f32) !void {
        for (graph.nodes.items, 0..) |node, i| {
            @memset(output[i], 0.0);

            var aggregated = try self.allocator.alloc(f32, self.input_dim);
            defer self.allocator.free(aggregated);
            @memset(aggregated, 0.0);

            for (node.neighbors.items) |neighbor_id| {
                const neighbor = &graph.nodes.items[neighbor_id];
                for (0..self.input_dim) |j| {
                    aggregated[j] += neighbor.features[j];
                }
            }

            const norm_factor = if (node.degree > 0)
                1.0 / @sqrt(@as(f32, @floatFromInt(node.degree)))
            else
                1.0;

            for (0..self.input_dim) |j| {
                aggregated[j] *= norm_factor;
                aggregated[j] += node.features[j];
            }

            for (0..self.output_dim) |j| {
                for (0..self.input_dim) |k| {
                    output[i][j] += aggregated[k] * self.weights[k * self.output_dim + j];
                }
                output[i][j] += self.bias[j];
                output[i][j] = if (output[i][j] > 0) output[i][j] else 0;
            }
        }
    }
};

const RelationalEncoder = struct {
    layers: std.ArrayList(GNNLayer),
    hidden_dims: []const usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, input_dim: usize, hidden_dims: []const usize) !RelationalEncoder {
        var layers = std.ArrayList(GNNLayer).init(allocator);

        var prev_dim = input_dim;
        for (hidden_dims) |dim| {
            const layer = try GNNLayer.init(allocator, prev_dim, dim);
            try layers.append(layer);
            prev_dim = dim;
        }

        return RelationalEncoder{
            .layers = layers,
            .hidden_dims = hidden_dims,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *RelationalEncoder) void {
        for (self.layers.items) |*layer| {
            layer.deinit();
        }
        self.layers.deinit();
    }

    pub fn encode(self: *RelationalEncoder, graph: *RelationalGraph) ![][]f32 {
        const num_nodes = graph.nodes.items.len;
        const final_dim = self.hidden_dims[self.hidden_dims.len - 1];

        var current_features = try self.allocator.alloc([]f32, num_nodes);
        for (current_features, 0..) |*feat, i| {
            feat.* = try self.allocator.dupe(f32, graph.nodes.items[i].features);
        }
        defer {
            for (current_features) |feat| {
                self.allocator.free(feat);
            }
            self.allocator.free(current_features);
        }

        var output_features = try self.allocator.alloc([]f32, num_nodes);
        for (output_features) |*feat| {
            feat.* = try self.allocator.alloc(f32, final_dim);
        }

        for (self.layers.items, 0..) |*layer, layer_idx| {
            var temp_output = try self.allocator.alloc([]f32, num_nodes);
            for (temp_output) |*feat| {
                feat.* = try self.allocator.alloc(f32, layer.output_dim);
            }

            var temp_graph = RelationalGraph{
                .nodes = std.ArrayList(GraphNode).init(self.allocator),
                .edge_types = graph.edge_types,
                .feature_dim = layer.input_dim,
                .allocator = self.allocator,
            };

            for (graph.nodes.items, 0..) |node, i| {
                var temp_node = try GraphNode.init(self.allocator, i, layer.input_dim);
                @memcpy(temp_node.features, current_features[i]);
                for (node.neighbors.items) |neighbor| {
                    try temp_node.addNeighbor(neighbor);
                }
                temp_node.degree = node.degree;
                try temp_graph.nodes.append(temp_node);
            }

            try layer.forward(&temp_graph, temp_output);

            for (temp_graph.nodes.items) |*node| {
                node.deinit(self.allocator);
            }
            temp_graph.nodes.deinit();

            for (current_features) |feat| {
                self.allocator.free(feat);
            }
            self.allocator.free(current_features);
            current_features = temp_output;

            if (layer_idx == self.layers.items.len - 1) {
                for (output_features, current_features) |out, curr| {
                    @memcpy(out, curr);
                }
            }
        }

        return output_features;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = RelationalGraph.init(allocator, 64);
    defer graph.deinit();

    const node0 = try graph.addNode();
    const node1 = try graph.addNode();
    const node2 = try graph.addNode();
    const node3 = try graph.addNode();

    try graph.addEdge(node0, node1, "friend");
    try graph.addEdge(node1, node2, "colleague");
    try graph.addEdge(node2, node3, "family");
    try graph.addEdge(node0, node3, "neighbor");

    var prng = std.Random.DefaultPrng.init(@intCast(std.time.timestamp()));
    const random = prng.random();

    var features = try allocator.alloc(f32, 64);
    defer allocator.free(features);

    for (0..4) |i| {
        for (features) |*f| {
            f.* = random.floatNorm(f32);
        }
        try graph.setNodeFeatures(i, features);
    }

    const hidden_dims = [_]usize{ 128, 256, 128 };
    var encoder = try RelationalEncoder.init(allocator, 64, &hidden_dims);
    defer encoder.deinit();

    const embeddings = try encoder.encode(&graph);
    defer {
        for (embeddings) |emb| {
            allocator.free(emb);
        }
        allocator.free(embeddings);
    }

    std.debug.print("Graph encoded successfully\n", .{});
    std.debug.print("Number of nodes: {d}\n", .{graph.nodes.items.len});
    std.debug.print("Embedding dimension: {d}\n", .{embeddings[0].len});

    for (embeddings, 0..) |emb, i| {
        var norm: f32 = 0.0;
        for (emb) |val| {
            norm += val * val;
        }
        norm = @sqrt(norm);
        std.debug.print("Node {d} embedding norm: {d:.4}\n", .{ i, norm });
    }
}
