const std = @import("std");
const Allocator = std.mem.Allocator;

const HungarianToken = struct {
    text: []const u8,
    prefix: ?[]const u8,
    root: []const u8,
    suffix: ?[]const u8,
    case_ending: ?[]const u8,

    pub fn deinit(self: *HungarianToken, allocator: Allocator) void {
        allocator.free(self.text);
        allocator.free(self.root);
        if (self.prefix) |p| allocator.free(p);
        if (self.suffix) |s| allocator.free(s);
        if (self.case_ending) |c| allocator.free(c);
    }
};

const HungarianMorphology = struct {
    prefixes: []const []const u8,
    suffixes: []const []const u8,
    case_endings: []const []const u8,
    allocator: Allocator,

    pub fn init(allocator: Allocator) !HungarianMorphology {
        const prefixes = [_][]const u8{
            "meg", "el", "fel", "le", "be", "ki", "át", "vissza", "össze", "szét",
        };
        const suffixes = [_][]const u8{
            "hat", "het", "ható", "hető", "ság", "ség", "talan", "telen", "atlan", "etlen",
        };
        const case_endings = [_][]const u8{
            "nak", "nek", "ban", "ben", "ba", "be", "ból", "ből", "ra", "re",
            "ról", "ről", "val", "vel", "hoz", "hez", "höz", "nál", "nél",
            "tól", "től", "ig", "ul", "ül", "ként", "ért",
        };

        const prefix_copy = try allocator.alloc([]const u8, prefixes.len);
        for (prefixes, prefix_copy) |p, *pc| {
            pc.* = try allocator.dupe(u8, p);
        }

        const suffix_copy = try allocator.alloc([]const u8, suffixes.len);
        for (suffixes, suffix_copy) |s, *sc| {
            sc.* = try allocator.dupe(u8, s);
        }

        const case_copy = try allocator.alloc([]const u8, case_endings.len);
        for (case_endings, case_copy) |c, *cc| {
            cc.* = try allocator.dupe(u8, c);
        }

        return HungarianMorphology{
            .prefixes = prefix_copy,
            .suffixes = suffix_copy,
            .case_endings = case_copy,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *HungarianMorphology) void {
        for (self.prefixes) |p| self.allocator.free(p);
        for (self.suffixes) |s| self.allocator.free(s);
        for (self.case_endings) |c| self.allocator.free(c);
        self.allocator.free(self.prefixes);
        self.allocator.free(self.suffixes);
        self.allocator.free(self.case_endings);
    }

    pub fn analyze(self: *HungarianMorphology, word: []const u8) !HungarianToken {
        var prefix: ?[]const u8 = null;
        var suffix: ?[]const u8 = null;
        var case_ending: ?[]const u8 = null;
        var root_start: usize = 0;
        var root_end: usize = word.len;

        for (self.prefixes) |p| {
            if (std.mem.startsWith(u8, word, p)) {
                prefix = try self.allocator.dupe(u8, p);
                root_start = p.len;
                break;
            }
        }

        for (self.case_endings) |c| {
            if (std.mem.endsWith(u8, word, c)) {
                case_ending = try self.allocator.dupe(u8, c);
                root_end = word.len - c.len;
                break;
            }
        }

        if (case_ending == null) {
            for (self.suffixes) |s| {
                if (std.mem.endsWith(u8, word, s)) {
                    suffix = try self.allocator.dupe(u8, s);
                    root_end = word.len - s.len;
                    break;
                }
            }
        }

        const root = try self.allocator.dupe(u8, word[root_start..root_end]);

        return HungarianToken{
            .text = try self.allocator.dupe(u8, word),
            .prefix = prefix,
            .root = root,
            .suffix = suffix,
            .case_ending = case_ending,
        };
    }
};

const CompoundSplitter = struct {
    dictionary: std.StringHashMap(void),
    allocator: Allocator,

    pub fn init(allocator: Allocator) CompoundSplitter {
        return CompoundSplitter{
            .dictionary = std.StringHashMap(void).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *CompoundSplitter) void {
        var it = self.dictionary.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.dictionary.deinit();
    }

    pub fn addWord(self: *CompoundSplitter, word: []const u8) !void {
        const word_copy = try self.allocator.dupe(u8, word);
        try self.dictionary.put(word_copy, {});
    }

    pub fn split(self: *CompoundSplitter, compound: []const u8) !std.ArrayList([]const u8) {
        var result = std.ArrayList([]const u8).init(self.allocator);

        if (compound.len <= 3) {
            try result.append(try self.allocator.dupe(u8, compound));
            return result;
        }

        var best_split = std.ArrayList([]const u8).init(self.allocator);
        try best_split.append(try self.allocator.dupe(u8, compound));
        var best_score: usize = 1;

        var i: usize = 3;
        while (i < compound.len - 2) : (i += 1) {
            const left = compound[0..i];
            const right = compound[i..];

            if (self.dictionary.contains(left)) {
                var right_split = try self.split(right);
                defer right_split.deinit();

                if (right_split.items.len + 1 > best_score) {
                    for (best_split.items) |item| {
                        self.allocator.free(item);
                    }
                    best_split.clearRetainingCapacity();

                    try best_split.append(try self.allocator.dupe(u8, left));
                    for (right_split.items) |item| {
                        try best_split.append(try self.allocator.dupe(u8, item));
                    }
                    best_score = best_split.items.len;
                }
            }
        }

        for (best_split.items) |_| {}
        result.deinit();
        return best_split;
    }
};

const HungarianNormalizer = struct {
    vowel_harmony_map: std.StringHashMap([]const u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator) !HungarianNormalizer {
        var vowel_harmony_map = std.StringHashMap([]const u8).init(allocator);

        const mappings = [_]struct { []const u8, []const u8 }{
            .{ "nak", "nek" },
            .{ "ban", "ben" },
            .{ "ba", "be" },
            .{ "ból", "ből" },
            .{ "ra", "re" },
            .{ "ról", "ről" },
            .{ "val", "vel" },
            .{ "hoz", "hez" },
            .{ "nál", "nél" },
            .{ "tól", "től" },
            .{ "ul", "ül" },
        };

        for (mappings) |mapping| {
            const key = try allocator.dupe(u8, mapping[0]);
            const value = try allocator.dupe(u8, mapping[1]);
            try vowel_harmony_map.put(key, value);
        }

        return HungarianNormalizer{
            .vowel_harmony_map = vowel_harmony_map,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *HungarianNormalizer) void {
        var it = self.vowel_harmony_map.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.vowel_harmony_map.deinit();
    }

    pub fn normalize(self: *HungarianNormalizer, token: *HungarianToken) !void {
        if (token.case_ending) |ending| {
            const has_back_vowel = blk: {
                for (token.root) |c| {
                    if (c == 'a' or c == 'o' or c == 'u') {
                        break :blk true;
                    }
                }
                break :blk false;
            };

            if (self.vowel_harmony_map.get(ending)) |front_variant| {
                if (!has_back_vowel) {
                    self.allocator.free(token.case_ending.?);
                    token.case_ending = try self.allocator.dupe(u8, front_variant);
                }
            }
        }

        _ = self;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var morphology = try HungarianMorphology.init(allocator);
    defer morphology.deinit();

    var normalizer = try HungarianNormalizer.init(allocator);
    defer normalizer.deinit();

    var splitter = CompoundSplitter.init(allocator);
    defer splitter.deinit();

    try splitter.addWord("ház");
    try splitter.addWord("ajtó");
    try splitter.addWord("kulcs");
    try splitter.addWord("autó");
    try splitter.addWord("pálya");

    const test_words = [_][]const u8{
        "megérthetetlen",
        "házban",
        "felolvassuk",
        "autópálya",
        "kulcsajtó",
    };

    for (test_words) |word| {
        std.debug.print("\nAnalyzing: {s}\n", .{word});

        var token = try morphology.analyze(word);
        defer token.deinit(allocator);

        try normalizer.normalize(&token);

        std.debug.print("  Root: {s}\n", .{token.root});
        if (token.prefix) |p| std.debug.print("  Prefix: {s}\n", .{p});
        if (token.suffix) |s| std.debug.print("  Suffix: {s}\n", .{s});
        if (token.case_ending) |c| std.debug.print("  Case: {s}\n", .{c});

        if (word.len > 6) {
            var parts = try splitter.split(word);
            defer {
                for (parts.items) |part| {
                    allocator.free(part);
                }
                parts.deinit();
            }

            if (parts.items.len > 1) {
                std.debug.print("  Compound parts:\n", .{});
                for (parts.items) |part| {
                    std.debug.print("    - {s}\n", .{part});
                }
            }
        }
    }
}
